import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.RefreshEntitlements{}
EMPTY = bytes.fromhex("")


def test_refresh_entitlements_encodes_to_its_golden():
    assert bytes(v2225.RefreshEntitlementsPacket()) == EMPTY


def test_refresh_entitlements_decodes_from_its_golden():
    assert v2225.RefreshEntitlementsPacket.from_bytes(EMPTY) == v2225.RefreshEntitlementsPacket()


def test_the_refresh_entitlements_body_reads_none_of_the_byte_behind_it():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2225.RefreshEntitlementsPacket.from_bytes(b"\x01")
